entries[327661] = { ["name"] = "Faewächter", ["text"] = "Pakt-Fähigkeit\n2% von Grundmana 40 Meter Reichweite\nSofort 1.5 min Abklingzeit\nRuft 3 Feenwächter herbei, die sich 20 Sek. lang um Eure Ziele kümmern.\n\nZornige Fee : Direkte Angriffe auf das Ziel stellen 0.5% Mana oder 3 Wahnsinn wieder her. Folgt Eurem 'Schattenwort: Schmerz'.\n\nWächterfee : Verringert den erlittenen Schaden um 20%. Folgt Eurem 'Machtwort: Schild'.\n\nGütige Fee : Erhöht die Abklingzeitrate einer wichtigen Fähigkeit Eures Ziels um 100%. Folgt Eurer [ Heilig : 'Blitzheilung' /\n\nDisziplin, Schatten\n'Schattenheilung' ]" }
