entries[328275] = { ["name"] = "Wildes Mal", ["text"] = "Pakt-Fähigkeit\n100 Meter Reichweite\nSofort\nRuft die Energie wilder Geister am Zielort hervor, die allen gegnerischen Zielen im Effektbereich (25% der Angriffskraft) Naturschaden zufügt und sie für 15 Sek. mit 'Wildes Mal' belegt.\n\nWährend die wilden Geister aktiv sind, fügt jede Schadensfähigkeit, die Ihr oder Euer Begleiter gegen ein Ziel im Effektbereich einsetzt, bis zu 5 zusätzlichen Zielen in der Nähe (38.5% der Angriffskraft) Naturschaden zu." }
entries[328276] = { ["name"] = "Marsch der Bußfertigen", ["text"] = "Unbegrenzte Reichweite\nSofort\nSobald er 70% Gesundheit erreicht, zieht Denathrius alle Spielercharaktere in die Mitte des Raums und befördert sie dann nach außen zum Rand.\n\nDie Bewegungsgeschwindigkeit von mit 'Bürde der Sünde' belegten Spielercharakteren ist um 20% pro Stapel verringert und sie können keine Fähigkeiten einsetzen.\n\nWenn Spielercharaktere sich Denathrius auf 16 Meter nähern, werden sie von 'Bürde der Sünde' erlöst." }
