entries[328281] = { ["name"] = "Segen des Winters", ["text"] = "Pakt-Fähigkeit\n5% von Grundmana 40 Meter Reichweite\nSofort 45 sek. Abklingzeit\nSegnet einen Verbündeten für 30 Sek. Dadurch verursachen seine Zauber und Fähigkeiten [((5 / 100 * Max(Angriffskraft, Zaubermacht) * (1 + Vielseitigkeit)))] Frostschaden und verringern die Bewegungsgeschwindigkeit von Gegnern um 5% sowie ihr Angriffstempo um 2%. Bis zu 10-mal stapelbar.\n\nSegen der Jahreszeiten: Wechselt nach dem Einsatz zum Frühling.\n(500ms Abklingzeit)" }
entries[328282] = { ["name"] = "Segen des Frühlings", ["text"] = "Pakt-Fähigkeit\n5% von Grundmana 40 Meter Reichweite\nSofort 45 sek. Abklingzeit\nSegnet einen Verbündeten für 30 Sek. und erhöht so seine hervorgerufene Heilung um 15% sowie seine erhaltene Heilung um 30%.\n\nSegen der Jahreszeiten: Wechselt nach dem Einsatz zum Sommer." }
